content.js_code:
// 对象.属性
objectName.propertyName
// 或 对象['属性']
objectName['propertyName']

var person = {
    name: "John", 
    age: 31, 
    favColor: "green",
    height: 183
};
var x = person.age;
var y = person['age'];

document.write(x);
document.write(y);

